import {renderLineMatchReview} from './line-match-review.js';
import {inboxRecord,saveInboxCase,backToInbox} from './workflow-bridge.js';
import {assertContext,sourceStamp} from './workflow-engine.js';
import {confirmSupplier} from './supplier.js';
import {newCase,prepareRequest,receiveRevision,resolveCase,recordEvent,caseExport} from './case-engine.js';
import {extractAndReview} from './extraction-review.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='invoicing-resolution-v1';let current=null,busy=false;try{current=JSON.parse(localStorage.getItem(key));if(current&&(!current.original||!current.po||!Array.isArray(current.events)))current=null;}catch{}
const root=document.createElement('section');root.id='cases-page';root.hidden=true;document.querySelector('.content').insertBefore(root,document.querySelector('footer'));
function save(){if(current?.inboxContext)saveInboxCase(current.inboxContext,current);try{localStorage.setItem(key,JSON.stringify(current));}catch{root.querySelector('[role=status]').textContent='Browser storage is full. Export the case to preserve it.';}}
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function startResolutionCase(invoice,po,context=null,lineDecisions=[]){if(busy)throw Error('Finish the revision upload first.');if(context){const doc=inboxRecord(context.id);assertContext(doc,context);current=doc.workflow?.case?structuredClone(doc.workflow.case):{...newCase(invoice,po,lineDecisions),id:'case-'+context.id,inboxContext:context};renderCase();save();document.querySelector('[data-page=cases]').click();return;}if(current&&!current.inboxContext&&JSON.stringify(current.original)===JSON.stringify(invoice)&&JSON.stringify(current.po)===JSON.stringify(po)&&JSON.stringify(current.comparison.lineDecisions??[])===JSON.stringify(lineDecisions)){document.querySelector('[data-page=cases]').click();return;}if(current&&!current.inboxContext&&!confirm('Replace the current standalone case? Export it first if needed.'))return;current=newCase(invoice,po,lineDecisions);renderCase();save();document.querySelector('[data-page=cases]').click();}
export function openInboxCase(doc){if(!doc.workflow?.case)throw Error('Compare the purchase order and start a resolution case first.');if(doc.workflow.sourceStamp!==sourceStamp(doc))throw Error('Invoice changed. Match the PO again.');current=structuredClone(doc.workflow.case);renderCase();document.querySelector('[data-page=cases]').click();}

function renderCase(){if(!current){root.innerHTML='<section class="panel"><div class="panel-heading"><div><h2>No resolution case yet</h2><p>Compare an invoice and purchase order, then select “Track correction & resolution.”</p></div></div></section>';return;}
 if(current.inboxContext){try{const d=inboxRecord(current.inboxContext.id);if(d?.status==='approved'){if(sourceStamp(d)!==current.inboxContext.stamp)throw Error('Invoice changed. Reopen from inbox.');}else assertContext(d,current.inboxContext);}catch(e){root.innerHTML='<section class="panel"><p>'+esc(e.message)+'</p><button class="text-button" id="stale-back">Back to inbox</button></section>';root.querySelector('button').onclick=backToInbox;return;}}
 const c=current,latest=c.revisions.at(-1),labels={open:'Open discrepancy',matched:'Matched · awaiting payment decision',revision_has_discrepancy:'Correction still has discrepancies',revision_ready:'Correction verified · review needed',resolved:'Resolved · payment not approved'};
 root.innerHTML=`${c.inboxContext?'<button class="text-button" id="case-back">← Back to invoice inbox</button>':''}<div class="result-banner"><div><span class="eyebrow">${esc(c.id)}</span><h2>${esc(labels[c.status])}</h2><p>Original: ${esc(c.original.number)} · PO: ${esc(c.po.number)} · Original difference: $${(c.comparison.differenceCents/100).toFixed(2)}</p></div><span class="payment-hold">${c.status==='resolved'||c.status==='matched'?'PAYMENT NOT APPROVED':'PAYMENT ON HOLD'}</span></div><div role="status" id="case-status"></div><div class="resolution-grid"><section class="panel"><div class="panel-heading"><h2>1. Prepare the correction request</h2></div><div class="resolution-body"><button id="case-draft" class="button secondary">Prepare evidence-based draft</button><label class="draft-label" for="case-message">Editable request</label><textarea id="case-message" rows="12">${esc(c.draft)}</textarea><div class="actions"><button id="save-case-draft" class="text-button">Save draft</button><button id="download-case-draft" class="text-button">Download draft</button></div><p class="hint">Nothing is sent from this demo. Record communication below after sending it yourself.</p><form id="case-contact"><label>Supplier contact or response note<input name="note" required placeholder="e.g. Supplier confirmed a corrected invoice is coming"></label><button class="button secondary">Record communication</button></form></div></section><section class="panel"><div class="panel-heading"><h2>2. Receive & verify the correction</h2></div><div class="resolution-body"><p>Upload the supplier’s revised invoice. Its vendor and PO must agree with this case.</p><input id="case-revision" type="file" accept=".json,.pdf,.png,.jpg,.jpeg,.webp"><button id="example-revision" class="button secondary">Load corrected example</button><p class="hint">The example uses the retained PO quantities and prices; it is labeled synthetic.</p>${latest?`<div class="hold-card"><strong>${esc(latest.document.number)}</strong><p>Revised total: $${latest.document.total.toFixed(2)} · PO total: $${c.po.total.toFixed(2)}</p><p>${latest.comparison.hasDiscrepancy?'Discrepancies remain. Case stays on hold.':'The verified products, quantities, unit prices and tax agree with the PO.'}</p><details><summary>Inspect revision and comparison evidence</summary><pre>${esc(JSON.stringify(latest,null,2))}</pre></details></div>`:''}<form id="resolve-case"><label class="review-confirm"><input type="checkbox" name="replacement" required> I verified this revised invoice replaces the original and resolves this discrepancy.</label><label>Verification note<input name="note" required placeholder="What did you check?"></label><button class="button primary" ${c.status!=='revision_ready'?'disabled':''}>Resolve discrepancy</button></form><p class="hint">Resolution records a human decision. It never approves or initiates payment.</p></div></section></div><section class="panel case-history"><div class="panel-heading"><h2>3. Case history & evidence</h2><button id="export-case" class="button secondary">Export case + reviewed data</button></div><div class="resolution-body"><details><summary>Original invoice and PO (preserved)</summary><pre>${esc(JSON.stringify({invoice:c.original,po:c.po,comparison:c.comparison},null,2))}</pre></details></div>${c.events.map(e=>`<div class="activity-item"><strong>${esc(e.action)}</strong> · ${esc(e.detail)}<small>${esc(e.at)}</small></div>`).join('')}<p class="match-note">History is local to this browser and is not a tamper-proof production audit log.</p></section>`;
 const q=s=>root.querySelector(s),status=s=>q('#case-status').textContent=s;if(c.inboxContext)q('#case-back').onclick=backToInbox;
 q('#case-draft').onclick=()=>{current=prepareRequest(current);renderCase();save();};q('#save-case-draft').onclick=()=>{current=recordEvent({...current,draft:q('#case-message').value},'Draft saved','User edited correction request.');save();status('Draft saved. Nothing sent.');};q('#download-case-draft').onclick=()=>{current={...current,draft:q('#case-message').value};save();download(current.draft,'correction-request.txt');};q('#case-contact').onsubmit=e=>{e.preventDefault();current=recordEvent(current,'Communication recorded',new FormData(e.target).get('note'));renderCase();save();};
 async function receive(d,decisions=[]){try{current=receiveRevision(current,d,decisions);renderCase();save();}catch(err){
  if(err.code==='LINE_MATCH_REVIEW'){
   status(err.message);
   const caseAtReview=current;
   const summarize=lines=>lines.map((line,index)=>({...line,id:index+1,number:index+1}));
   q('#case-status').append(renderLineMatchReview({candidates:err.candidates,invoiceLines:summarize(d.lines),poLines:summarize(current.po.lines),
    onReview:async (match,decision)=>{try{
     if(current!==caseAtReview)throw Error('Case changed. Upload the revision again.');
     await receive(d,[...decisions,{invoiceLine:match.invoiceLine,poLine:match.poLine,decision}]);
    }catch(e){status(e.message);}}}));
   return;
  }
  if(err.code!=='SUPPLIER_REVIEW')throw err;status(err.message);const form=document.createElement('form');form.innerHTML='<label><input type="checkbox" required> I verified the revised invoice supplier identity.</label><label>Revision supplier verification note<input name="note" required></label><button class="button secondary">Confirm supplier & verify revision</button>';const caseAtReview=current;form.onsubmit=async event=>{event.preventDefault();try{if(current!==caseAtReview)throw Error('Case changed. Upload the revision again.');await receive(confirmSupplier(d,current.po,new FormData(form).get('note')));}catch(e){status(e.message);}};q('#case-status').append(form);}}
 q('#example-revision').onclick=()=>{const d=structuredClone(c.po);d.type='invoice';d.number=c.original.number+'-R1';d.note='Synthetic corrected example. Not received from a real supplier.';receive(d);};
 q('#case-revision').onchange=async e=>{const file=e.target.files[0];if(!file||busy)return;busy=true;q('#example-revision').disabled=true;q('#case-revision').disabled=true;try{let d;if(file.name.toLowerCase().endsWith('.json')){if(file.size>500000)throw Error('JSON must be under 500 KB.');d=JSON.parse(await file.text());}else d=await extractAndReview(file,'invoice',status);if(d){delete d.supplierReview;await receive(d);}}catch(err){status(err.message);}finally{busy=false;if(q('#case-revision')){q('#case-revision').disabled=false;q('#case-revision').value='';q('#example-revision').disabled=false;}}};
 q('#resolve-case').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target);current=resolveCase(current,f.get('replacement')==='on',f.get('note'));renderCase();save();}catch(err){status(err.message);}};q('#export-case').onclick=()=>download(JSON.stringify(caseExport(current),null,2),'reviewed-resolution-case.json');if(c.inboxContext&&inboxRecord(c.inboxContext.id)?.status==='approved'){root.querySelectorAll('input,textarea,button').forEach(el=>{if(!['case-back','export-case'].includes(el.id))el.disabled=true;});status('Approved for export. Case evidence is read-only; payment has not been initiated.');}
}
window.addEventListener('inbox-ready',renderCase);
window.addEventListener('invoicing-reset',()=>{current=null;localStorage.removeItem(key);renderCase();});renderCase();
